/// <reference lib="webworker" />
import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching'
import { registerRoute, NavigationRoute } from 'workbox-routing'
import { CacheFirst, NetworkOnly, StaleWhileRevalidate } from 'workbox-strategies'
import { ExpirationPlugin } from 'workbox-expiration'

declare const self: ServiceWorkerGlobalScope

// Clean up old caches
cleanupOutdatedCaches()

// Precache assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || [])

// Fallback to index.html for SPA client navigation except /api routes
const handler = new StaleWhileRevalidate({ cacheName: 'focusos-navigation' })
const navigationRoute = new NavigationRoute(handler, {
  denylist: [/^\/api/],
})
registerRoute(navigationRoute)

// Never cache Supabase API calls or auth endpoints
registerRoute(
  ({ url }) =>
    url.hostname.includes('supabase.co') ||
    url.pathname.startsWith('/rest') ||
    url.pathname.startsWith('/auth'),
  new NetworkOnly()
)

// Font caching (Google fonts or local font assets)
registerRoute(
  ({ request }) => request.destination === 'font',
  new CacheFirst({
    cacheName: 'focusos-fonts',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 10,
        maxAgeSeconds: 60 * 60 * 24 * 365, // 1 year
      }),
    ],
  })
)

// Push notification event listener
self.addEventListener('push', (event) => {
  if (!event.data) return

  let data = { title: 'FocusOS Reminder', body: 'You have scheduled tasks today.', url: '/daily' }
  try {
    data = event.data.json()
  } catch {
    data.body = event.data.text()
  }

  const options: NotificationOptions = {
    body: data.body,
    icon: '/pwa-192x192.png',
    badge: '/favicon.svg',
    data: {
      url: data.url || '/daily',
    },
    tag: 'focusos-reminder',
  }

  event.waitUntil(self.registration.showNotification(data.title, options))
})

// Notification click event listener
self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const targetUrl = event.notification.data?.url || '/daily'

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          client.navigate(targetUrl)
          return client.focus()
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl)
      }
    })
  )
})

// Message handler for immediate update
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting()
  }
})
